mapper.select:

WHERE p.id = #{playlistId}
  AND (p.owner_user_id = #{viewerId}
       OR (p.is_public = 1 AND (p.status IS NULL OR p.status = 'PUBLISHED')))
ORDER BY pb.song_id, c.create_time DESC, c.id DESC

SELECT id AS playlistId, title, cover_url AS coverUrl
FROM tb_playlist
WHERE is_public = 1 AND (status IS NULL OR status = 'PUBLISHED') AND style IN

    #{style}

AND id NOT IN

    #{id}

ORDER BY RAND()
LIMIT #{limit}
